var SoundManager = class {
	constructor() {
		this.ctx = null;
		this.enabled = true;
	}
	getContext() {
		if (typeof window === "undefined") return null;
		if (!this.ctx) {
			const AudioCtx = window.AudioContext || window.webkitAudioContext;
			if (AudioCtx) this.ctx = new AudioCtx();
		}
		if (this.ctx && this.ctx.state === "suspended") this.ctx.resume().catch(() => {});
		return this.ctx;
	}
	setEnabled(val) {
		this.enabled = val;
	}
	isEnabled() {
		return this.enabled;
	}
	playFocus() {
		if (!this.enabled) return;
		try {
			const ctx = this.getContext();
			if (!ctx) return;
			const osc = ctx.createOscillator();
			const gain = ctx.createGain();
			osc.type = "sine";
			osc.frequency.setValueAtTime(440, ctx.currentTime);
			osc.frequency.exponentialRampToValueAtTime(880, ctx.currentTime + .04);
			gain.gain.setValueAtTime(.04, ctx.currentTime);
			gain.gain.exponentialRampToValueAtTime(.001, ctx.currentTime + .05);
			osc.connect(gain);
			gain.connect(ctx.destination);
			osc.start();
			osc.stop(ctx.currentTime + .05);
		} catch {}
	}
	playSelect() {
		if (!this.enabled) return;
		try {
			const ctx = this.getContext();
			if (!ctx) return;
			const osc = ctx.createOscillator();
			const gain = ctx.createGain();
			osc.type = "triangle";
			osc.frequency.setValueAtTime(523.25, ctx.currentTime);
			osc.frequency.setValueAtTime(659.25, ctx.currentTime + .06);
			osc.frequency.setValueAtTime(783.99, ctx.currentTime + .12);
			gain.gain.setValueAtTime(.08, ctx.currentTime);
			gain.gain.exponentialRampToValueAtTime(.001, ctx.currentTime + .22);
			osc.connect(gain);
			gain.connect(ctx.destination);
			osc.start();
			osc.stop(ctx.currentTime + .22);
		} catch {}
	}
	playBack() {
		if (!this.enabled) return;
		try {
			const ctx = this.getContext();
			if (!ctx) return;
			const osc = ctx.createOscillator();
			const gain = ctx.createGain();
			osc.type = "sine";
			osc.frequency.setValueAtTime(587.33, ctx.currentTime);
			osc.frequency.exponentialRampToValueAtTime(329.63, ctx.currentTime + .12);
			gain.gain.setValueAtTime(.06, ctx.currentTime);
			gain.gain.exponentialRampToValueAtTime(.001, ctx.currentTime + .14);
			osc.connect(gain);
			gain.connect(ctx.destination);
			osc.start();
			osc.stop(ctx.currentTime + .14);
		} catch {}
	}
};
